// Rastreio falso: devolve o que houver por código, ou null (código desconhecido).
export function rastreioFalso(porCodigo = {}) {
  const chamadas = []
  return {
    chamadas,
    async rastrear(codigo) {
      chamadas.push(codigo)
      return porCodigo[codigo] ?? null
    }
  }
}
